 function nowPage(){return `<section class="now-page"><p class="panel-eyebrow">An interest snapshot</p><h2 class="panel-title" id="panel-title">Currently in<br><span class="soft-text">my orbit.</span></h2><p class="panel-lead">A few threads that keep finding their way into what I make.</p><div class="orbit-cards"><article><span class="orbit-symbol">⌘</span><span class="section-kicker">Building</span><h3>Digital products.</h3><p>Code, project management, and an entrepreneurial mindset in the same orbit.</p></article><article><span class="orbit-symbol">${icon('plane')}</span><span class="section-kicker">Exploring</span><h3>Travel tech.</h3><p>The possibilities between a digital product and a better journey.</p><button class="text-action tactile" data-open="travel">Explore the globe ↗</button></article><article><span class="orbit-symbol">✧</span><span class="section-kicker">Noticing</span><h3>How things feel.</h3><p>Thoughtful interfaces, beautiful color, and small details that invite curiosity.</p></article></div><button class="workbench-card tactile" data-open="goprava"><span class="workbench-orb">G↗</span><div><span class="section-kicker">On the workbench</span><strong>GoPrava</strong><small>An ongoing project, still taking shape.</small></div><span>↗</span></button></section>`}
 function travelPage(){return `<section class="travel-page"><p class="panel-eyebrow">The travel-tech thread</p><h2 class="panel-title" id="panel-title">A world worth<br><span class="soft-text">exploring.</span></h2><p class="panel-lead">A few places connected through Tourfixer. Spin the globe and follow your curiosity.</p><div class="globe-layout"><div class="globe-stage"><canvas id="travel-globe" tabindex="0" role="img" aria-label="Interactive globe. Drag or use the arrow keys to rotate. Select a city below to focus it."></canvas><div class="globe-controls"><button class="glass tactile" data-globe-turn="-1" aria-label="Rotate globe left">←</button><span>Drag to explore</span><button class="glass tactile" data-globe-turn="1" aria-label="Rotate globe right">→</button></div></div><div class="globe-copy"><span class="section-kicker">From Tourfixer’s world</span><div class="city-choices">${cities.map((c,i)=>`<button class="city-choice tactile ${i===0?'active':''}" data-city="${c.id}" aria-pressed="${i===0}">${c.name}</button>`).join('')}</div><article class="city-story" aria-live="polite"><h3 id="city-title">${cities[0].name}</h3><p id="city-copy">${cities[0].copy}</p><a class="panel-link tactile" id="city-link" href="${cities[0].url}" target="_blank" rel="noopener">Explore with Tourfixer ↗</a></article><p class="globe-note">An interest map of the project’s destinations.</p></div></div><p class="map-credit">Land outlines: <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener">Natural Earth</a>, public domain.</p></section>`}
 function secretPage(){const count=game.found.length;if(count<3)return `<section class="secret-intro"><div class="secret-emblem">✧</div><p class="panel-eyebrow">A secret in plain sight</p><h2 class="panel-title" id="panel-title">Follow the<br><span class="soft-text">hidden sparks.</span></h2><p class="panel-lead">Three tiny sparks are hiding around the bubble playground. Collect them to unlock a space for curiosity.</p><div class="spark-meter" aria-label="${count} of 3 sparks collected">${[0,1,2].map(i=>`<span class="${i<count?'found':''}">✧</span>`).join('')}</div><p class="game-progress-copy">${count} of 3 found. No rush. Just curiosity.</p><button class="panel-link tactile" data-find-spark>Back to the hunt ↗</button></section>`;return `<section class="secret-reward"><p class="panel-eyebrow">You found the curious corner</p><h2 class="panel-title" id="panel-title">Follow your curiosity.<br><span class="soft-text">Your universe.</span></h2><p class="panel-lead">Tap the sky to leave some light. Make a constellation that’s entirely yours.</p><canvas id="constellation" tabindex="0" role="img" aria-label="Your constellation. Tap to add stars, or press Enter to add a star."></canvas><div class="constellation-actions"><button class="panel-link tactile" data-save-stars>Keep my constellation ↓</button><button class="text-action tactile" data-game-reset>Find the sparks again ↻</button></div><p class="game-progress-copy">Keep making things. Keep following your curiosity.</p></section>`}
 function positionSparks(fieldTop=0,fieldHeight=stageH){const mobile=stageW<=760,positions=mobile?[[.20,.16],[.83,.53],[.37,.91]]:[[.59,.40],[.89,.24],[.44,.70]];const stageRect=stage.getBoundingClientRect(),dockRect=$('.dock').getBoundingClientRect(),dock={left:dockRect.left-stageRect.left,right:dockRect.right-stageRect.left,top:dockRect.top-stageRect.top,bottom:dockRect.bottom-stageRect.top};$$x('[data-spark]').forEach((button,i)=>{let x=clamp(stageW*positions[i][0]-22,8,stageW-52),y=(mobile?fieldTop:0)+fieldHeight*positions[i][1]-22;if(!mobile)y=Math.min(y,Math.max(8,window.innerHeight-stageRect.top-65));const overlapsDock=x<dock.right+12&&x+44>dock.left-12&&y<dock.bottom+12&&y+44>dock.top-12;if(overlapsDock)y=Math.max(8,dock.top-64);button.style.left=`${x}px`;button.style.top=`${y}px`})}
