    ctx.save();ctx.translate(cx,cy);ctx.rotate(-.24);ctx.beginPath();ctx.ellipse(0,0,r*1.14,r*.31,0,0,Math.PI*2);ctx.strokeStyle=colors.accentC+'45';ctx.lineWidth=1;ctx.stroke();ctx.restore();
    const grad=ctx.createRadialGradient(cx-r*.35,cy-r*.45,r*.05,cx,cy,r);grad.addColorStop(0,'#ffffff');grad.addColorStop(.72,colors.auraB+'65');grad.addColorStop(1,colors.accentB+'5c');ctx.fillStyle=grad;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ffffffdd';ctx.lineWidth=2;ctx.stroke();
    ctx.strokeStyle=colors.accentB+'25';ctx.lineWidth=.7;for(const line of grid)gridLine(line,r,cx,cy);
