  const observer=new ResizeObserver(fit),paletteObserver=new MutationObserver(()=>{colorsDirty=true;queueDraw()});observer.observe(canvas);paletteObserver.observe(document.documentElement,{attributes:true,attributeFilter:['style']});fit();queueDraw();
